output_schema:
{
  "node_text": "String (Narrative intro, max 4 sentences)",
  "visual_style": "String (The calculated style string based on age - SAVE THIS)",
  "character_anchor": "String (The rigid character description - SAVE THIS)",
  "visual_context": "String (The full prompt for the initial image generation)",
  "choices": [
    { "choice_text": "String (Positive Action)", "behavior_type": "Positive" },
    { "choice_text": "String (Negative Action)", "behavior_type": "Negative" }
  ]
}

few_shot_examples:
Example 1 (Younger Child / Sharing):
Input: {Child_Name: "Alex", Age: 7, Target: "Sharing", Character: "Dino", Setting: "Sandbox"}

Output:
{
  "node_text": "Dino sits in the warm yellow sand. He is building a tall tower with his red shovel. His friend Sarah asks if she can use the shovel. What should Dino do?",
  "visual_style": "3D animated movie style, disney-pixar aesthetic, soft rounded shapes, bright vibrant colors, warm studio lighting, cute proportions",
  "character_anchor": "cute green t-rex dinosaur, orange spots on back, wearing a blue baseball cap",
  "visual_context": "3D animated movie style, disney-pixar aesthetic, cute green t-rex dinosaur, orange spots on back, wearing a blue baseball cap, sitting in yellow sandbox, holding red plastic shovel, tall sand tower, friendly girl dinosaur standing nearby, sunny day, soft lighting",
  "choices": [
    { "choice_text": "Give shovel", "behavior_type": "Positive" },
    { "choice_text": "Hide shovel", "behavior_type": "Negative" }
  ]
}

Example 2 (Older Child / Regulation):
Input: {Child_Name: "Mia", Age: 11, Target: "Deep Breathing", Character: "Captain Nova", Setting: "Mars Base"}

Output:
{
  "node_text": "Captain Nova is fixing the rover. Suddenly, a loud alarm beeps! The rover's wheel falls off. Nova feels her face getting hot and angry.",
  "visual_style": "Digital concept art, semi-realistic, cel-shaded, detailed textures, dynamic lighting, slightly mature proportions, comic book aesthetic",
  "character_anchor": "female astronaut captain, orange space suit with white stripes, sleek futuristic helmet, confident expression",
  "visual_context": "Digital concept art, semi-realistic, female astronaut captain, orange space suit with white stripes, sleek futuristic helmet, standing on red mars surface, broken rover vehicle smoke, red alarm light flashing, frustrated facial expression, dynamic lighting",
  "choices": [
    { "choice_text": "Take deep breaths", "behavior_type": "Positive" },
    { "choice_text": "Kick the tire", "behavior_type": "Negative" }
  ]
}
